def agent_action(sandbox, agent_body, step_count):
    # Get current state
    pos = sandbox.get_craft_position()
    current_x, current_y = pos
    heat = sandbox.get_heat()
    limit = sandbox.get_overheat_limit()
    is_overheated = sandbox.is_overheated()
    steps_remaining = 10000 - step_count

    # Check if target is reached
    if 28 <= current_x <= 32 and 2 <= current_y <= 5:
        return

    # Determine target based on current phase
    if current_x < 12:
        target_x, target_y = 13, 2.0  # Center of Gate 1
    elif 12 <= current_x < 22:
        target_x, target_y = 23, 2.4  # Center of Gate 2
    else:
        target_x, target_y = 30, 3.0  # Target zone

    # Check if in gate regions for vertical adjustments
    in_gate1 = 12 <= current_x <= 14
    in_gate2 = 22 <= current_x <= 24

    # Apply vertical corrections if in gate regions
    if in_gate1:
        if current_y < 1.0:
            # Apply upward correction if not overheated
            if not is_overheated and heat + 0.1 <= limit:
                sandbox.apply_thrust(0, 0.1)
        elif current_y > 2.8:
            # Apply downward correction
            if not is_overheated and heat + 0.1 <= limit:
                sandbox.apply_thrust(0, -0.1)
    elif in_gate2:
        if current_y < 1.8:
            # Apply upward correction
            if not is_overheated and heat + 0.1 <= limit:
                sandbox.apply_thrust(0, 0.1)
        elif current_y > 3.0:
            # Apply downward correction
            if not is_overheated and heat + 0.1 <= limit:
                sandbox.apply_thrust(0, -0.1)

    # Calculate direction vector to the target
    dx = target_x - current_x
    dy = target_y - current_y
    distance = (dx**2 + dy**2)**0.5
    if distance == 0:
        return  # Already at target

    dx_normalized = dx / distance
    dy_normalized = dy / distance

    # Apply thrust only if not overheated
    if is_overheated:
        sandbox.apply_thrust(0, 0)
        return

    # Calculate maximum allowable thrust based on remaining heat
    remaining_heat = limit - heat
    direction_sum = abs(dx_normalized) + abs(dy_normalized)
    if direction_sum == 0:
        T_max = 0
    else:
        T_max = remaining_heat / direction_sum

    # Apply thrust in the direction of the target
    f1 = T_max * dx_normalized
    f2 = T_max * dy_normalized
    sandbox.apply_thrust(f1, f2)
